import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Comprendre les classements et compétitions","description":"","frontmatter":{"title":"Comprendre les classements et compétitions","docId":"user.points.rankings","translationKey":"user.points.rankings","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"1c45cf6e9355092d95dc9f90025b2965e0a6a4cddb453fb25680192ab41e873c","translationRevision":"267e433365a264faff533593247e3712b10513b2cbdce046e8ef2410630e9028","order":30},"headers":[],"relativePath":"fr/user/points/rankings.md","filePath":"fr/user/points/rankings.md","lastUpdated":1795727787000}`),s={name:`fr/user/points/rankings.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="understand-rankings-and-competitions" tabindex="-1">Comprendre les classements et compétitions <a class="header-anchor" href="#understand-rankings-and-competitions" aria-label="Permalink to “Comprendre les classements et compétitions”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Choisir la vue de classement appropriée et reconnaître les limites de l’espace de classements en développement. Une activité entrante est nécessaire pour obtenir des scores pertinents. Commencez par le classement ordinaire de <a href="./rules.html">Points</a> ou les panneaux des meilleurs spectateurs de <a href="./../live/feed.html">Live feed</a> pour simplement examiner les spectateurs actuels.</p><h2 id="use-the-right-view" tabindex="-1">Utiliser la bonne vue <a class="header-anchor" href="#use-the-right-view" aria-label="Permalink to “Utiliser la bonne vue”">​</a></h2><ol><li>Dans <strong>Points</strong>, recherchez un spectateur et triez par points, niveau ou identité. Actualisez avant de comparer un ajustement manuel à une attribution.</li><li>Dans <strong>Live feed</strong>, examinez les panneaux de classement de spectateurs disponibles. Ils peuvent recevoir des instantanés du moteur de classement indépendamment du tableau des soldes de points.</li><li>Pour une incrustation, ouvrez <a href="./../overlays/">Overlays</a>, sélectionnez le type de classement et examinez les options de source. Une source de classement configurée doit exister avant que sa sortie puisse apparaître.</li></ol><p>L’espace dédié <strong>Rankings &amp; competitions</strong> est expérimental. Sa route d’interface est <code>#/rankings</code>, mais il est volontairement masqué dans la navigation principale et n’est pas restauré comme onglet de démarrage. L’absence d’entrée latérale ne signifie pas que la route ou le moteur de classement a été supprimé.</p><h2 id="configure-an-experimental-ranking" tabindex="-1">Configurer un classement expérimental <a class="header-anchor" href="#configure-an-experimental-ranking" aria-label="Permalink to “Configurer un classement expérimental”">​</a></h2><p>Si votre environnement expose cet espace, commencez avec un créateur, une salle, un regroupement par utilisateur et une fenêtre de session. Ajoutez une métrique annoncée, telle que <code>tiktok.like</code> / <code>like.count</code>, avec un poids de <code>1</code>. Fixez une limite de résultats modeste et créez la définition. Le formulaire prend aussi en charge des fenêtres glissantes et quotidiennes, avec des bornes explicites de durée ou d’événements, ou un décalage de fuseau horaire.</p><p>Lisez l’instantané obtenu avant d’introduire d’autres sources. La pause et la reprise affectent la collecte du classement ; la réinitialisation efface intentionnellement son état. Les options de compétition et les sources liées aux votes ont leurs propres règles de regroupement. Ne supposez pas qu’une réinitialisation des points réinitialise aussi une compétition, ni que tous les regroupements personnalisés fonctionnent avec toutes les métriques.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Résultat attendu et état”">​</a></h2><p>Les classements ordinaires sont disponibles ; la page de gestion dédiée reste expérimentale. Les scores proviennent de l’hôte et non du comptage des lignes affichées dans le flux. Ce guide ne démontre ni la validation en diffusion réelle/OBS ni celle de toutes les combinaisons de compétition.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to “Récupération”">​</a></h2><p>Vérifiez le créateur, la salle, l’activation des sources, la fenêtre et l’état de pause lorsque les scores restent vides. Retirez les combinaisons source/regroupement non prises en charge plutôt que d’inventer des noms de champs. Préservez les données importantes par des <a href="./../preferences/backups.html">sauvegardes</a> avant toute réinitialisation, et incluez l’identifiant de définition et le code de diagnostic dans votre rapport.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Détails de fonctionnement”">​</a></h2><p>Le tableau Points demande 100 spectateurs et filtre/trie uniquement ces lignes. Actualiser ou trier par nom ne recherche pas toute la base. Les classements du fil affichent 10 lignes par session créateur/salle : diamants des cadeaux pour Top et quantités pour Likes, avec un suivi limité à 5 000 spectateurs. Ils ne mesurent pas les points enregistrés. Comparez d’abord unités et périodes.</p><p>Essayez interactivement avant de toucher à votre vraie configuration :</p>`,16),t(d,{scenario:`points`,locale:`fr`,panel:`points`,title:`Essayez classements et points des spectateurs`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Opérations en ligne de commande <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Opérations en ligne de commande”">​</a></h2><p>Chaque opération de ce guide est aussi disponible depuis la CLI — hors ligne, scriptable et adaptée aux agents. Les lignes d&#39;usage sont la syntaxe du parseur et restent en anglais dans toutes les langues.</p><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>lister les définitions de classement</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>métriques disponibles pour les définitions de classement</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>créer une définition de classement</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>mettre à jour une définition de classement</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>lire un classement</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>classement actuel d&#39;un ranking</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>supprimer un classement <strong>destructif</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>réinitialiser l&#39;état accumulé <strong>destructif</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>suspendre l&#39;accumulation</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>reprendre l&#39;accumulation</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>ajouter une contribution externe</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>lister les compétitions</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>lire une compétition</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>créer une compétition</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>mettre à jour une compétition</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>supprimer une compétition <strong>destructif</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>état actuel de la compétition</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>résultats finaux ou intermédiaires</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>enregistrer une action de compétition</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>marquer une action comme incertaine</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>résoudre une action incertaine</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>démarrer une compétition</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>terminer une compétition <strong>destructif</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>candidats au titre de gagnant</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>sélectionner le gagnant</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>suspendre une compétition</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>reprendre une compétition</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>annuler une compétition <strong>destructif</strong></td></tr></tbody></table><p>Consultez la <a href="./../../developer/cli.html">référence complète des commandes</a> pour les conventions, la sortie JSON et les marqueurs d’opérations destructives.</p>`,5)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};